mapper.select:
select o.id, o.order_no, o.type, o.status, o.total_quantity, o.total_kinds, o.remark, o.audit_time, o.audit_user, au.name as audit_user_name, o.create_time, o.create_user, cu.name as create_user_name, o.update_time from stock_order o left join employee cu on cu.id = o.create_user left join employee au on au.id = o.audit_user
and o.type = #{type}
and o.status = #{status}
and o.order_no like concat('%', #{orderNo}, '%')
and exists ( select 1 from stock_order_item i where i.order_id = o.id and (i.product_code like concat('%', #{code}, '%') or i.sku_code like concat('%', #{code}, '%')) )
and o.create_time >= #{beginDate}
and o.create_time < date_add(#{endDate}, interval 1 day)
order by o.create_time desc, o.id desc

select o.order_no, o.type, o.status, o.remark, o.create_time, cu.name as create_user_name, o.audit_time, au.name as audit_user_name, i.product_code, i.sku_code, i.product_name, i.sku_attrs, i.quantity from stock_order o left join employee cu on cu.id = o.create_user left join employee au on au.id = o.audit_user left join stock_order_item i on i.order_id = o.id
and o.type = #{type}
and o.status = #{status}
and o.order_no like concat('%', #{orderNo}, '%')
and (i.product_code like concat('%', #{code}, '%') or i.sku_code like concat('%', #{code}, '%'))
and o.create_time >= #{beginDate}
and o.create_time < date_add(#{endDate}, interval 1 day)
order by o.create_time desc, o.id desc, i.id
